  "technical_and_design_decisions": [
    "Leverage Spring Boot auto-configuration mechanisms for implementing the standalone Boot-based ModuleRunner for container-managed environments.",
    "Reuse and adapt existing Spring XD gpfdist sink logic into a Spring Batch ItemWriter component for the OOTB jdbcgpfdist batch job.",
    "Extend Spring XD Admin REST API controllers to add bulk retrieval endpoints (/metrics/counters/all, /metrics/gauges/all, /metrics/rich-gauges/all).",
    "Expose externalized configuration properties for Sqoop metastore database connection settings (driver, url, username, password).",
    "Utilize Spring Test profiles and modular test configurations to isolate real repository integration tests from light mock-based tests."
  ],
  "assumptions": [
    "Target environment supports Java 17+ and Spring XD / Spring Framework conventions.",
    "Test environments for GemFire, HAWQ/GPDB, and HDFS are available for integration testing.",
    "Existing gpfdist sink code is functional and can be refactored cleanly into batch writer components.",
    "Single developer is performing all activities including design, implementation, documentation, and unit/integration testing."
  ],
  "activities": [
    {
      "activity_id": "ACT-1",
      "activity_name": "Implement Configurable Sqoop Metastore (U1)",
      "activity_description": "Expose configuration properties and update initialization code to allow users to override the default Sqoop metastore database implementation.",
      "most_likely_effort": 2.5
    },
    {
      "activity_id": "ACT-2",
      "activity_name": "Document HDFS-Backed Module Registry (U2)",
      "activity_description": "Draft recommended configuration guidelines, properties, and usage examples for HDFS-backed module registry setup in user documentation.",
      "most_likely_effort": 1.0
    },
    {
      "activity_id": "ACT-3",
      "activity_name": "REST API Bulk Metrics Endpoints (U3)",
      "activity_description": "Implement REST API endpoints (/metrics/counters/all, /metrics/gauges/all, /metrics/rich-gauges/all) to fetch metric collections in a single request, along with controller unit tests.",
      "most_likely_effort": 2.5
    },
    {
      "activity_id": "ACT-4",
      "activity_name": "Boot-based ModuleRunner Development (U4)",
      "activity_description": "Develop Boot-based ModuleRunner for running modules in container-managed environments without requiring full xd-container infrastructure.",
      "most_likely_effort": 3.5
    },
    {
      "activity_id": "ACT-5",
      "activity_name": "GemFire Source Authentication & Docs (U5)",
      "activity_description": "Enable native GemFire security/authentication properties in the GemFire source module and document required security configurations.",
      "most_likely_effort": 2.5
    },
    {
      "activity_id": "ACT-6",
      "activity_name": "OOTB jdbcgpfdist Batch Job Implementation (U6)",
      "activity_description": "Build an OOTB batch job reading from JDBC and writing to HAWQ/GPDB by adapting existing gpfdist sink logic into a batch gpfdist writer.",
      "most_likely_effort": 4.0
    },
