      "activity_name": "Test Infrastructure Refactoring for Mocks vs Real Repositories (U7)",
      "activity_description": "Decouple repository mocks from real repository implementations in test framework to support lightweight testing against thin dependency layers.",
      "most_likely_effort": 3.0
    },
    {
      "activity_id": "ACT-8",
      "activity_name": "Migrate Reactor Data Processor Module to Core (U8)",
      "activity_description": "Move Reactor-based data processor module from spring-xd-modules repo into core repository, update build scripts, packages, and core integration tests.",
      "most_likely_effort": 2.0
    },
    {
      "activity_id": "ACT-9",
      "activity_name": "End-to-End Integration Testing & Verification",
      "activity_description": "Perform overall build verification, end-to-end integration testing across all updated components, and final doc checks.",
